effect.shader:
float beHashA(vec2 p, float t) { return fract(sin(dot(p + t, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
vec2 uv = acScreenNorm;
vec2 px = vec2(1.0) / max(acScreenSize, vec2(1.0));
float t = acTime * max(speed, 0.0) + seed * 13.0;
float s1 = sin(t * 1.7) + 0.5 * sin(t * 3.9 + 1.3);
float s2 = cos(t * 1.3) + 0.5 * cos(t * 3.1 + 4.1);
vec2 off = vec2(s1, s2) * 0.375 * amount * px;
vec4 src = texture2DCv(inputImg.texture, clamp(uv + off, vec2(0.0), vec2(1.0)));
gl_FragColor = vec4(src.rgb, src.a);
}
